// index.mjs
import path from 'node:path';

console.log(import.meta.dirname);   // Node 20.11+
console.log(import.meta.filename);
console.log(path.join(import.meta.dirname, 'data', 'users.json'));

// ---- math.cjs (CommonJS) ----
function add(a, b) { return a + b; }
module.exports = { add };

// ---- app.cjs ----
const { add } = require('./math.cjs');
console.log(add(2, 3));

// ---- math.mjs (ES module) ----
export function add(a, b) { return a + b; }
export default function sub(a, b) { return a - b; }

// ---- app.mjs ----
import sub, { add } from './math.mjs';
import { readFile } from 'node:fs/promises';
console.log(add(2, 3), sub(5, 1));
const text = await readFile(new URL('./math.mjs', import.meta.url), 'utf8'); // top-level await
console.log(text.length > 0);

// counter.js
let count = 0;
module.exports = { inc: () => ++count };

// main.js
const a = require('./counter');
const b = require('./counter');
console.log(a === b);        // true  -> same cached object
a.inc();
console.log(b.inc());        // 2     -> shared state
console.log(require.resolve('./counter'));

import { builtinModules } from 'node:module';

const pub = builtinModules.filter((m) => !m.startsWith('_'));
console.log(pub.length, 'public built-in modules');
console.log(pub.slice(0, 8));
